programs.sync:
component Sync {
    state a: Int = 0;
    state b: Int = 0;
    state c: Int = 0;
    state m: Int = 0;
    state s: String = "x";
    state note: String = "idle";
    on Set { a = 1; b = 100 / m; c = 5; }
    on SetLate { a = 1; c = 5; b = 100 / m; }
    on First { b = 100 / m; a = 1; }
    on Typed { a = 2; b = s - 1; }
    on Good { a = 3; b = 100 / 4; }
    on Fix { m = 5; }
    on Probe { m = m; }
    view { Column { Button { label: "Set" on: Set } Button { label: "SetLate" on: SetLate } Button { label: "First" on: First } Button { label: "Typed" on: Typed } Button { label: "Good" on: Good } Button { label: "Fix" on: Fix } Button { label: "Probe" on: Probe } Text { "a={a} b={b} c={c} m={m} note={note}" } } }
}

programs.awaits:
component Awaits {
    state a: Int = 0;
    state b: Int = 0;
    state c: Int = 0;
    state m: Int = 0;
    state note: String = "idle";
    state r: Result[Int, String] = Ok(0);
    on Slow { note = "loading"; c = 7; r = await(sleep(1000)); note = "resumed"; b = 100 / m; a = 9; }
    on Other { a = 4; }
    on Fix { m = 5; }
    on Probe { m = m; }
    on Tick { note = "loading"; c = c + 1; r = await(sleep(1000)); note = "done"; a = a + 1; }
    view { Column { Button { label: "Slow" on: Slow } Button { label: "Other" on: Other } Button { label: "Fix" on: Fix } Button { label: "Probe" on: Probe } Button { label: "Tick" on: Tick } Text { "a={a} b={b} c={c} m={m} note={note}" } } }
}

programs.net:
component Net {
    requires Network;
    state a: Int = 0;
    state b: Int = 0;
    state c: Int = 0;
    state m: Int = 0;
    state note: String = "idle";
    state r: Result[String, String] = Ok("");
    on Load { note = "loading"; c = 1; r = await(net.get("missing.txt")); note = match r { Ok(_) => { "ok" } Err(_) => { "err" } Cancelled => { "cancelled" } }; a = 2; }
    on LoadBad { c = 1; r = await(net.get("missing.txt")); b = 100 / m; a = 5; }
    on Probe { m = m; }
    view { Column { Button { label: "Load" on: Load } Button { label: "Probe" on: Probe } Button { label: "LoadBad" on: LoadBad } Text { match r { Ok(_) => { "r=ok" } Err(_) => { "r=err" } Cancelled => { "r=cancelled" } } } Text { "a={a} b={b} c={c} m={m} note={note}" } } }
}
